          "버물리에스솔타입은 현대약품(주)이 1997-11-25 허가받은 일반의약품이에요. 식약처 품목번호 199702966, ATC 분류 D04A (ANTIPRURITICS, INCL. ANTIHISTAMINES, ANESTHETICS, ETC.)예요. 성상은 \"특이한 향이 있는 무색 액제\"이라고 식약처 허가사항이 명시했어요.\n\n식약처 등록 원료약품 분량은 100밀리리터중 디펜히드라민염산염, 디부카인염산염, L-멘톨, 살리실산메틸, dl-캄파, 에녹솔론이에요. 시중에서 다른 표현으로 알려진 정보가 있을 수 있지만, 이 글은 식약처 e약은요(nedrug.mfds.go.kr) 등록 사실만을 출처로 작성됐어요.\n\n같은 199702966 품목번호의 다른 박스 단위가 있어요. 박스 단위가 달라도 1포·1정·1g·1mL 단위 약효는 같고, 단가·재고 부담·휴대성에서 차이가 나요. 매일 사용하는 분이라면 큰 박스가 단가 면에서 합리적이고, 단발성 시도라면 작은 박스가 부담이 적어요.",
